\set ON_ERROR_STOP on
begin;
create function pg_temp.rc1_assert(ok boolean,label text) returns void language plpgsql as $$begin
 if ok is distinct from true then raise exception 'RC1 FAIL: %',label; end if;raise notice 'RC1 PASS: %',label;end$$;
create function pg_temp.rc1_denied(statement text) returns boolean language plpgsql as $$begin execute statement;return false;exception when insufficient_privilege then return true;end$$;
create function pg_temp.rc1_invalid(statement text) returns boolean language plpgsql as $$begin execute statement;return false;exception when invalid_parameter_value then return true;end$$;
grant execute on function pg_temp.rc1_assert(boolean,text),pg_temp.rc1_denied(text),pg_temp.rc1_invalid(text) to anon,authenticated,service_role;
insert into auth.sessions(id,user_id) values
 ('70000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001'),
 ('70000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002'),
 ('70000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001'),
 ('70000000-0000-4000-8000-000000000004','20000000-0000-4000-8000-000000000001');
insert into public.vendor_routes(id,vendor_id,name,waypoints) values
 ('80000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','Synthetic push route','[{"latitude":0,"longitude":0,"orderIndex":0},{"latitude":0,"longitude":0.01,"orderIndex":1}]');
insert into public.purchase_intents(id,consumer_id,vendor_id,route_id,location,created_at) values
 ('81000000-0000-4000-8000-000000000000','10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000001',extensions.st_setsrid(extensions.st_makepoint(0.008,0),4326)::extensions.geography,clock_timestamp()-interval '1 minute');
select pg_temp.rc1_assert((select bool_and(relrowsecurity) from pg_class where oid in ('private.interest_push_devices'::regclass,'private.interest_push_revocations'::regclass,'private.interest_push_progress'::regclass,'private.interest_push_outbox'::regclass)),'RLS on all push storage');
select pg_temp.rc1_assert((select bool_and(not has_function_privilege('anon',p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('register_interest_push_device','revoke_interest_push_device','verify_interest_push','claim_interest_push_job','publish_route_location','interest_push_job_binding','interest_push_job_eligible','finish_interest_push_job','retry_interest_push_job','invalidate_interest_push_device')),'anon denied new APIs');
set local role authenticated;
select pg_temp.rc1_assert(pg_temp.rc1_denied($q$select * from private.interest_push_devices$q$),'client cannot read tokens');
select pg_temp.rc1_assert(pg_temp.rc1_denied($q$select * from private.interest_push_outbox$q$),'client cannot inspect outbox');
select pg_temp.rc1_assert(pg_temp.rc1_denied($q$select public.claim_interest_push_job()$q$),'client cannot claim worker job');
select pg_temp.rc1_assert(pg_temp.rc1_denied($q$select private.push_eligible(null,null,null,null,null)$q$),'client cannot bypass owner checked verification facade');
select pg_temp.rc1_assert(pg_temp.rc1_denied($q$select public.register_interest_push_device('90000000-0000-4000-8000-000000000001','synthetic-token-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000001')$q$),'missing auth denied');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"session_id":"70000000-0000-4000-8000-000000000003"}',true);
select pg_temp.rc1_assert(pg_temp.rc1_denied($q$select public.register_interest_push_device('90000000-0000-4000-8000-000000000001','synthetic-token-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000001')$q$),'consumer cannot register vendor device');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
select pg_temp.rc1_assert(pg_temp.rc1_denied($q$select public.register_interest_push_device('90000000-0000-4000-8000-000000000001','synthetic-token-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000001')$q$),'foreign session cannot register');
select set_config('request.jwt.claims','{"session_id":"70000000-0000-4000-8000-000000000001"}',true);
select set_config('request.jwt.claims','{"session_id":"70000000-0000-4000-8000-000000000001","is_anonymous":true}',true);
select pg_temp.rc1_assert(pg_temp.rc1_denied($q$select public.register_interest_push_device('90000000-0000-4000-8000-000000000001','synthetic-token-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000001')$q$),'anonymous signed-in session cannot register vendor push');
select set_config('request.jwt.claims','{"session_id":"70000000-0000-4000-8000-000000000001"}',true);
select pg_temp.rc1_assert(public.register_interest_push_device('90000000-0000-4000-8000-000000000001','synthetic-token-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000001')='90000000-0000-4000-8000-000000000001','registration confirms installation');
select pg_temp.rc1_assert(pg_temp.rc1_invalid($q$select public.register_interest_push_device('90000000-0000-4000-8000-000000000002','short','a0000000-0000-4000-8000-000000000001')$q$),'invalid token rejected');
reset role;
select set_config('test.active_since',(select active_since::text from private.interest_push_devices),true);
select pg_temp.rc1_assert((select count(*)=0 from private.interest_push_outbox),'registration never backfills old interests');
set local role authenticated;
select public.register_interest_push_device('90000000-0000-4000-8000-000000000001','synthetic-token-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000001');
select pg_temp.rc1_assert(pg_temp.rc1_invalid($q$select public.publish_route_location('80000000-0000-4000-8000-000000000001',0,0.002,5,clock_timestamp()-interval '40 seconds')$q$),'stale captured fix rejected');
select pg_temp.rc1_assert(pg_temp.rc1_invalid($q$select public.publish_route_location('80000000-0000-4000-8000-000000000001',0,0.002,51,clock_timestamp()-interval '1 millisecond')$q$),'inaccurate fix rejected');
select public.publish_route_location('80000000-0000-4000-8000-000000000001',0.1,0.002,5,clock_timestamp()-interval '1 millisecond');
select public.publish_route_location('80000000-0000-4000-8000-000000000001',0,0.002,5,clock_timestamp()-interval '1 millisecond');
reset role;
select pg_temp.rc1_assert((select valid from private.interest_push_progress),'valid fix recovers after invalid first fix');
select pg_temp.rc1_assert((select accuracy_m=5 and updated_at<clock_timestamp() from public.vendor_locations where vendor_id='30000000-0000-4000-8000-000000000001'),'publication preserves accuracy and capture time');
select pg_temp.rc1_assert((select active_since::text=current_setting('test.active_since') from private.interest_push_devices),'heartbeat does not reset new-interest cutoff');
update public.purchase_intents set status='cancelled' where id='81000000-0000-4000-8000-000000000000';
insert into public.purchase_intents(id,consumer_id,vendor_id,route_id,location,created_at) values
 ('81000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000001',extensions.st_setsrid(extensions.st_makepoint(0.008,0),4326)::extensions.geography,clock_timestamp()),
 ('81000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000001',extensions.st_setsrid(extensions.st_makepoint(0.001,0),4326)::extensions.geography,clock_timestamp());
select pg_temp.rc1_assert((select count(*)=1 from private.interest_push_outbox),'only new eligible point ahead enqueued');
update public.purchase_intents set location=extensions.st_setsrid(extensions.st_makepoint(0.007,0),4326)::extensions.geography where id='81000000-0000-4000-8000-000000000002';
select pg_temp.rc1_assert((select count(*)=1 from private.interest_push_outbox),'updating old ineligible intent never generates a new job');
set local role authenticated;
select pg_temp.rc1_assert(public.verify_interest_push('80000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001'),'owner verifies current eligible protocol');
select set_config('request.jwt.claims','{"session_id":"70000000-0000-4000-8000-000000000004"}',true);
select pg_temp.rc1_assert(not public.verify_interest_push('80000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001'),'same owner with a different session cannot use old binding');
select set_config('request.jwt.claims','{"session_id":"70000000-0000-4000-8000-000000000001"}',true);
select pg_temp.rc1_assert(not public.verify_interest_push('80000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000000','90000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001'),'cancelled old protocol fails verification');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"session_id":"70000000-0000-4000-8000-000000000002"}',true);
select pg_temp.rc1_assert(not public.verify_interest_push('80000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001'),'other vendor cannot verify private protocol');
select public.revoke_interest_push_device('90000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001');
reset role;
select pg_temp.rc1_assert((select revoked_at is null from private.interest_push_devices where owner_id='20000000-0000-4000-8000-000000000001'),'other user cannot revoke owner device');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"session_id":"70000000-0000-4000-8000-000000000001"}',true);
select public.publish_route_location('80000000-0000-4000-8000-000000000001',0,0.009,5,clock_timestamp()-interval '1 millisecond');
select pg_temp.rc1_assert(not public.verify_interest_push('80000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001'),'impossible jump invalidates alerts');
select public.publish_route_location('80000000-0000-4000-8000-000000000001',0,0.002,5,clock_timestamp()-interval '1 millisecond');
select pg_temp.rc1_assert(public.verify_interest_push('80000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001'),'fix recovers against last accepted progress');
select public.register_interest_push_device('90000000-0000-4000-8000-000000000001','synthetic-token-bbbbbbbbbbbb','a0000000-0000-4000-8000-000000000002');
select pg_temp.rc1_assert(not public.verify_interest_push('80000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001'),'old token version rejected after rotation');
select public.revoke_interest_push_device('90000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001');
select pg_temp.rc1_assert(public.verify_interest_push('80000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000002'),'late old-version revoke preserves renewed binding');
reset role;
select pg_temp.rc1_assert((select active_since::text=current_setting('test.active_since') from private.interest_push_devices where owner_id='20000000-0000-4000-8000-000000000001'),'token rotation preserves active cutoff');
set local role service_role;
select pg_temp.rc1_assert(pg_temp.rc1_denied($q$select token from private.interest_push_devices$q$),'worker cannot read tokens without claimed-job RPC');
select set_config('test.claim',public.claim_interest_push_job()::text,true);
select pg_temp.rc1_assert(current_setting('test.claim')::jsonb->>'protocolId'='81000000-0000-4000-8000-000000000001','worker claims eligible job');
select pg_temp.rc1_assert(public.claim_interest_push_job() is null,'leased job cannot be claimed twice');
select pg_temp.rc1_assert(public.interest_push_job_binding((current_setting('test.claim')::jsonb->>'id')::uuid,(current_setting('test.claim')::jsonb->>'claimToken')::uuid)->>'version'='a0000000-0000-4000-8000-000000000002','worker reads latest token version through owned lease');
select pg_temp.rc1_assert(public.interest_push_job_binding((current_setting('test.claim')::jsonb->>'id')::uuid,'ffffffff-ffff-4fff-8fff-ffffffffffff') is null,'wrong claim cannot read token');
select pg_temp.rc1_assert(public.interest_push_job_eligible((current_setting('test.claim')::jsonb->>'id')::uuid,(current_setting('test.claim')::jsonb->>'claimToken')::uuid),'worker rechecks eligibility');
select pg_temp.rc1_assert(not public.finish_interest_push_job((current_setting('test.claim')::jsonb->>'id')::uuid,'ffffffff-ffff-4fff-8fff-ffffffffffff','provider-accepted'),'stale ACK cannot finish another lease');
reset role;
update public.vendors set is_online=false where id='30000000-0000-4000-8000-000000000001';
set local role service_role;
select pg_temp.rc1_assert(not public.interest_push_job_eligible((current_setting('test.claim')::jsonb->>'id')::uuid,(current_setting('test.claim')::jsonb->>'claimToken')::uuid),'pause blocks queued push');
reset role;
update public.vendors set is_online=true where id='30000000-0000-4000-8000-000000000001';
update public.purchase_intents set status='cancelled' where id='81000000-0000-4000-8000-000000000001';
set local role service_role;
select pg_temp.rc1_assert(not public.interest_push_job_eligible((current_setting('test.claim')::jsonb->>'id')::uuid,(current_setting('test.claim')::jsonb->>'claimToken')::uuid),'cancellation before send blocks job');
select pg_temp.rc1_assert(public.retry_interest_push_job((current_setting('test.claim')::jsonb->>'id')::uuid,(current_setting('test.claim')::jsonb->>'claimToken')::uuid,3600),'retry stores provider backoff');
reset role;
select pg_temp.rc1_assert((select next_attempt_at<=expires_at and status='pending' and attempts=1 from private.interest_push_outbox),'retry is bounded by TTL');
update private.interest_push_outbox set next_attempt_at=clock_timestamp()-interval '1 second';
set local role service_role;
select set_config('test.claim2',public.claim_interest_push_job()::text,true);
select pg_temp.rc1_assert((current_setting('test.claim2')::jsonb->>'claimToken')<>(current_setting('test.claim')::jsonb->>'claimToken'),'new attempt rotates lease token');
select pg_temp.rc1_assert(not public.finish_interest_push_job((current_setting('test.claim')::jsonb->>'id')::uuid,(current_setting('test.claim')::jsonb->>'claimToken')::uuid,'provider-accepted'),'previous attempt cannot ACK current claim');
select pg_temp.rc1_assert(not public.invalidate_interest_push_device('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001'),'UNREGISTERED for old version does not revoke new token');
reset role;
update private.interest_push_outbox set lease_until=clock_timestamp()-interval '1 second';
set local role service_role;
select set_config('test.claim3',public.claim_interest_push_job()::text,true);
select pg_temp.rc1_assert((current_setting('test.claim3')::jsonb->>'claimToken')<>(current_setting('test.claim2')::jsonb->>'claimToken'),'expired lease can be reclaimed with new token');
select pg_temp.rc1_assert(not public.finish_interest_push_job((current_setting('test.claim2')::jsonb->>'id')::uuid,(current_setting('test.claim2')::jsonb->>'claimToken')::uuid,'provider-accepted'),'expired worker cannot finish reclaimed job');
reset role;
update private.interest_push_outbox set attempts=5;
set local role service_role;
select pg_temp.rc1_assert(public.retry_interest_push_job((current_setting('test.claim3')::jsonb->>'id')::uuid,(current_setting('test.claim3')::jsonb->>'claimToken')::uuid),'retry handles attempt ceiling');
reset role;
select pg_temp.rc1_assert((select status='failed' from private.interest_push_outbox),'attempt ceiling terminates job');
reset role;
set local role authenticated;
select public.revoke_interest_push_device('90000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000002');
select pg_temp.rc1_assert(pg_temp.rc1_denied($q$select public.register_interest_push_device('90000000-0000-4000-8000-000000000001','synthetic-token-bbbbbbbbbbbb','a0000000-0000-4000-8000-000000000002')$q$),'late registration cannot resurrect revoked version');
select public.revoke_interest_push_device('90000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000003');
select pg_temp.rc1_assert(pg_temp.rc1_denied($q$select public.register_interest_push_device('90000000-0000-4000-8000-000000000002','synthetic-token-cccccccccccc','a0000000-0000-4000-8000-000000000003')$q$),'revoke before first registration leaves tombstone');
select public.register_interest_push_device('90000000-0000-4000-8000-000000000001','synthetic-token-dddddddddddd','a0000000-0000-4000-8000-000000000004');
reset role;
update private.interest_push_devices set expires_at=clock_timestamp()-interval '1 second' where owner_id='20000000-0000-4000-8000-000000000001';
select pg_temp.rc1_assert(not private.push_eligible('80000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001'),'expired device fails closed');
update private.interest_push_devices set expires_at=clock_timestamp()+interval '1 hour';
update auth.sessions set not_after=clock_timestamp()-interval '1 second' where id='70000000-0000-4000-8000-000000000001';
select pg_temp.rc1_assert(not private.push_eligible('80000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001'),'expired auth session fails closed');
select pg_temp.rc1_assert((select ambiguous from private.push_projection('[{"latitude":0,"longitude":0,"orderIndex":0},{"latitude":0,"longitude":0.01,"orderIndex":1},{"latitude":0,"longitude":0,"orderIndex":2}]',0,0.005)),'overlapping return route is ambiguous');
select pg_temp.rc1_assert((select abs(along_m-555.975)<0.001 and cross_m<0.001 and not ambiguous from private.push_projection('[{"latitude":0,"longitude":0,"orderIndex":0},{"latitude":0,"longitude":0.01,"orderIndex":1}]',0,0.005)),'projection numeric parity with RouteProgress');
rollback;
